//! Byte-parity tests against outputs produced by the REAL photon-node wasm
//! running under Node.js/V8 (files generated by /tmp/gen-images.js).
//!
//! NOTE (bwrap sandbox): every bash call gets a FRESH private /tmp, so
//! /tmp/imgtest/ does not persist between calls. Generate the fixtures
//! (node scripts/gen-photon-ground-truth.mjs) AND run `cargo test
//! -p pi-photon` in the SAME bash call.
use pi_photon::PhotonImage;

fn gt(name: &str) -> Vec<u8> {
    std::fs::read(format!("/tmp/imgtest/gt-{}", name)).unwrap()
}

#[test]
fn ground_truth_byte_parity() {
    for (file, label) in [
        ("small.png", "small-png"),
        ("large.png", "large-png"),
        ("tall.jpg", "tall-jpg"),
        ("img.bmp", "bmp"),
        ("small.gif", "gif"),
        ("small.webp", "webp"),
    ] {
        let bytes = std::fs::read(format!("/tmp/imgtest/{}", file)).unwrap();
        let img = PhotonImage::new_from_byteslice(&bytes).unwrap();
        let (ow, oh) = (img.width(), img.height());

        // decode -> PNG re-encode round trip
        let rt = img.get_bytes().unwrap();
        assert_eq!(rt, gt(&format!("{}-roundtrip.png", label)), "{} roundtrip", label);

        // resize path
        let mut tw = ow;
        let mut th = oh;
        if tw > 2000 {
            th = ((th as f64 * 2000.0 / tw as f64).round()) as u32;
            tw = 2000;
        }
        if th > 2000 {
            tw = ((tw as f64 * 2000.0 / th as f64).round()) as u32;
            th = 2000;
        }
        if tw != ow || th != oh {
            let resized = img.resize(tw, th).unwrap();
            assert_eq!(resized.get_bytes().unwrap(), gt(&format!("{}-resized.png", label)), "{} resized png", label);
            for q in [80u8, 85, 70, 55, 40] {
                assert_eq!(
                    resized.get_bytes_jpeg(q).unwrap(),
                    gt(&format!("{}-resized-q{}.jpg", label, q)),
                    "{} resized jpeg q{}",
                    label,
                    q
                );
            }
        }
    }
}
